CREATE TABLE "baselines" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "baselines_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"kind" text NOT NULL,
	"code" text NOT NULL,
	"name" text NOT NULL,
	"lobs" text[] DEFAULT '{}'::text[] NOT NULL,
	"valid_from" date DEFAULT now() NOT NULL,
	"valid_to" date,
	CONSTRAINT "baselines_kind" CHECK ("baselines"."kind" IN ('carrier', 'state', 'lob')),
	CONSTRAINT "baselines_state_code" CHECK ("baselines"."kind" <> 'state' OR "baselines"."code" ~ '^[A-Z]{2}$')
);
